/* ===================== BÀI 21 · SS:SP và thao tác stack ===================== */
/* Bài 21 · SS:SP và thao tác stack (AMTS-EMB-002-M06-L01, X86-021) — sinh bởi tools/author/mpu8086/l21.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P21=[{"label": "Ví dụ: PUSH, POP và thanh ghi SP", "code": "; Ví dụ 1: PUSH, POP và thanh ghi SP\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 1234H\n        MOV     BX, 0ABCDH\n        PUSH    AX                      ; SP giảm 2, ghi 34 12\n        PUSH    BX                      ; SP giảm 2, ghi CD AB\n        POP     CX                      ; đọc word ở đỉnh: CX = ABCDh\n        POP     DX                      ; DX = 1234h, SP về giá trị cũ\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bấm Từng bước và nhìn phần Ngăn xếp: PUSH AX làm SP giảm từ 0100h xuống 00FEh và ghi 34 12; PUSH BX ghi CD AB ở 00FCh. POP CX lấy word ở đỉnh (ABCDh), POP DX lấy 1234h; SP về 0100h nhưng byte cũ vẫn còn trong vùng SS:00FC của phần Bộ nhớ. PUSH r tốn 11 chu kỳ, POP r 8. Đoán trước: trước PUSH BX, SP bằng bao nhiêu? Đáp án 00FEh."}, {"label": "Ví dụ: vào sau ra trước, đảo 4 phím", "code": "; Ví dụ 2: vào sau, ra trước — đảo thứ tự 4 phím\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     CX, 4\ndoc:\n        MOV     AH, 08H                 ; đọc một phím, không hiện\n        INT     21H                     ; AL = mã ASCII\n        PUSH    AX                      ; PUSH chỉ nhận 16 bit: cất cả AX\n        LOOP    doc\n        MOV     CX, 4\nxuat:\n        POP     DX                      ; DL = phím cất sau cùng\n        MOV     AH, 02H\n        INT     21H                     ; in DL\n        LOOP    xuat\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "ABCD", "note": "Dữ liệu nhập ABCD. Vòng đầu PUSH AX bốn lần (AH = 08h đi kèm, nên word cất là 0841h, 0842h…). Vòng sau POP DX lấy ra D trước: màn hình in DCBA. Xem bốn word trong phần Ngăn xếp trước khi vòng in bắt đầu. Đoán trước: lần POP DX đầu tiên, DL bằng ký tự nào? Đáp án D (44h)."}, {"label": "Ví dụ: PUSH/POP thanh ghi đoạn và ô nhớ", "code": "; Ví dụ 3: PUSH/POP thanh ghi đoạn và ô nhớ\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\na       DW      1234H\nb       DW      0\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        PUSH    DS                      ; 10 chu kỳ\n        POP     ES                      ; ES = DS, 8 chu kỳ\n        PUSH    a                       ; FF 36: 16 + 6 = 22 chu kỳ\n        POP     b                       ; 8F 06: 17 + 6 = 23 chu kỳ\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "PUSH DS / POP ES chép DS sang ES mà không dùng AX (10 + 8 chu kỳ). PUSH a / POP b chép ô nhớ sang ô nhớ: b = 1234h. Cách này tốn 22 + 23 = 45 chu kỳ, so với 20 chu kỳ của MOV AX, a / MOV b, AX. Đoán trước: sau POP ES, ES bằng DS không? Đáp án có (0712h trên trình mô phỏng)."}, {"label": "Lỗi: khôi phục sai thứ tự", "code": "; Ví dụ 4 (lỗi): khôi phục sai thứ tự\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     CX, 1111H\n        MOV     DX, 2222H\n        PUSH    CX                      ; cất CX trước\n        PUSH    DX                      ; rồi DX\n        MOV     CX, 0                   ; dùng CX, DX vào việc khác\n        MOV     DX, 0\n        POP     CX                      ; SAI: lấy ra word cất sau cùng (DX cũ)\n        POP     DX                      ; DX nhận CX cũ\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: cất CX rồi DX nhưng lại POP CX trước. POP lấy word cất sau cùng (2222h, giá trị cũ của DX) nên CX = 2222h, DX = 1111h: hai thanh ghi đổi chỗ, không có thông báo lỗi nào. Sửa: POP DX rồi POP CX (thứ tự ngược với PUSH). Đoán trước: sau POP CX, CX bằng bao nhiêu? Đáp án 2222h."}, {"label": "Lỗi: PUSH hằng số không có trên 8086", "code": "; Ví dụ 5 (lỗi dịch): 8086 không có PUSH hằng số\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        PUSH    5                       ; có từ 80186, 8086 không có\n        POP     AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi dịch cố ý: PUSH 5 là lệnh của 80186 trở lên. Trên 8086 phải đưa hằng vào thanh ghi rồi PUSH thanh ghi: MOV AX, 5 / PUSH AX. Tương tự PUSH AL cũng báo lỗi vì PUSH chỉ nhận 16 bit."}, {"label": "Lỗi: tràn ngăn xếp đè lên biến", "code": "; Ví dụ 6 (lỗi): ngăn xếp 16 byte bị đẩy 9 word\n        .MODEL  SMALL\n        .STACK  10H                     ; chỉ 16 byte = 8 word\n        .DATA\nbuf     DB      14 DUP('.')\ncanh    DW      1234H                   ; nằm sát dưới đáy vùng ngăn xếp\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     CX, 9\nday:\n        PUSH    CX                      ; word thứ 9 rơi ra ngoài vùng\n        LOOP    day\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: .STACK 10h chỉ có 8 word nhưng vòng lặp PUSH 9 lần. Mở phần Bộ nhớ ở đoạn dữ liệu, nhìn biến canh: 8 lần đầu ghi vào vùng ngăn xếp (0010h–001Fh), lần thứ 9 (CX = 1) ghi vào 000Eh, canh từ 1234h thành 0001h. CPU không báo gì. Sửa: xin .STACK đủ lớn và giữ PUSH/POP cân bằng. Đoán trước: trước lần PUSH thứ 9, SP bằng bao nhiêu? Đáp án 0010h."}, {"label": "Ví dụ: PUSHF/POPF giữ cờ", "code": "; Ví dụ 7: PUSHF/POPF giữ cờ qua một đoạn tính toán\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 0FFH\n        ADD     AL, 1                   ; CF = 1\n        PUSHF                           ; cất FLAGS\n        MOV     AL, 1\n        ADD     AL, 1                   ; CF = 0\n        POPF                            ; CF = 1 trở lại\n        MOV     DL, '0'\n        ADC     DL, 0                   ; DL = '0' + CF\n        MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "ADD AL, 1 với AL = FFh cho CF = 1 (cùng ZF = 1). PUSHF cất word cờ F257h. Phép cộng thứ hai xóa CF, POPF nạp lại word cũ nên CF = 1 trở lại; ADC DL, 0 cộng CF vào '0' nên màn hình in 1. Nhìn các cờ đổi màu ở phần Thanh ghi. Đoán trước: ngay trước POPF, CF bằng mấy? Đáp án 0."}, {"label": "Ví dụ: đổi chỗ qua ngăn xếp hay XCHG", "code": "; Ví dụ 8: đổi chỗ AX, BX: qua ngăn xếp hay XCHG\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 1\n        MOV     BX, 2\n        PUSH    AX                      ; cách 1: 4 lệnh, 4 byte\n        PUSH    BX\n        POP     AX                      ; AX = 2\n        POP     BX                      ; BX = 1\n        XCHG    AX, BX                  ; cách 2: 1 lệnh, 1 byte\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Hai cách đổi chỗ AX và BX: bốn lệnh qua ngăn xếp tốn 11 + 11 + 8 + 8 = 38 chu kỳ, 4 byte; XCHG AX, BX (mã 93h) chỉ 3 chu kỳ, 1 byte. Sau cách 1, AX = 2, BX = 1; XCHG đổi lại AX = 1, BX = 2. Đoán trước: sau POP AX, AX bằng bao nhiêu? Đáp án 0002h."}];
const sim21=makeX86Sim(document.getElementById("x86-l21"),{id:"s21",presets:P21,file:"BAI21.ASM"});
makeX86Ex(document.getElementById("ex-l21"),sim21,[{"t": "Đảo thứ tự 5 phím", "d": "Đọc lần lượt 5 phím bằng INT 21h hàm 08h (không hiện), rồi in 5 phím đó theo thứ tự ngược lại bằng INT 21h hàm 02h. Ví dụ gõ ABCDE thì in EDCBA. Dùng ngăn xếp để cất phím. Kết thúc bằng INT 21h hàm 4Ch. Phím là ký tự ASCII in được (20h–7Eh).", "start": "; Bài tập 1: in 5 phím theo thứ tự ngược\n; Code mẫu đọc và in ngay từng phím (đúng thứ tự gõ).\n; Hãy sửa để in ngược lại bằng ngăn xếp.\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     CX, 5\ndoc:\n        MOV     AH, 08H                 ; đọc một phím\n        INT     21H\n        MOV     DL, AL\n        MOV     AH, 02H                 ; in ngay: chưa đảo thứ tự\n        INT     21H\n        LOOP    doc\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "ABCDE", "out": "EDCBA"}, {"in": "12345", "out": "54321"}, {"in": "aaaab", "out": "baaaa"}, {"in": "AB   ", "out": "   BA"}, {"in": "x+y=z", "out": "z=y+x"}, {"in": "ZZZZZ", "out": "ZZZZZ"}]}, {"t": "Kiểm tra ngoặc bằng ngăn xếp", "d": "Đọc lần lượt các phím bằng INT 21h hàm 08h cho tới khi gặp dấu chấm (.). Mỗi phím trước dấu chấm là một trong bốn ký tự ( ) [ ]. In YES nếu các ngoặc đóng mở đúng cặp và đúng thứ tự lồng nhau, ngược lại in NO. Dãy rỗng (chỉ có dấu chấm) là đúng. Có thể in kết quả ngay khi phát hiện sai. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: kiểm tra ngoặc ( ) [ ] đóng mở đúng cặp\n; Code mẫu chỉ ĐẾM số ngoặc đang mở, không phân biệt\n; loại ngoặc nên sai với \"(]\" và \"([)]\". Hãy sửa\n; bằng ngăn xếp: gặp ngoặc mở thì PUSH, gặp ngoặc\n; đóng thì POP và so loại.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nyes     DB      'YES$'\nno      DB      'NO$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        XOR     CX, CX                  ; số ngoặc đang mở\ndoc:\n        MOV     AH, 08H\n        INT     21H\n        CMP     AL, '.'                 ; dấu chấm: hết dữ liệu\n        JE      het\n        CMP     AL, '('\n        JE      mo\n        CMP     AL, '['\n        JE      mo\n        JCXZ    sai                     ; ngoặc đóng mà không còn ngoặc mở\n        DEC     CX\n        JMP     doc\nmo:\n        INC     CX\n        JMP     doc\nhet:\n        JCXZ    dung\nsai:\n        MOV     DX, OFFSET no\n        JMP     inra\ndung:\n        MOV     DX, OFFSET yes\ninra:\n        MOV     AH, 09H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "([]).", "out": "YES"}, {"in": "(].", "out": "NO"}, {"in": "((.", "out": "NO"}, {"in": "()).", "out": "NO"}, {"in": ".", "out": "YES"}, {"in": "[()()].", "out": "YES"}, {"in": "([)].", "out": "NO"}, {"in": "].", "out": "NO"}]}, {"t": "Ghi ngược 4 phím nhanh hơn", "d": "Đọc lần lượt 4 phím bằng INT 21h hàm 08h và ghi chúng vào mảng kq (4 byte) theo thứ tự ngược: phím thứ nhất vào kq[3], phím thứ tư vào kq[0]. Không in gì; kết thúc bằng INT 21h hàm 4Ch. Code mẫu đúng nhưng đi qua ngăn xếp nên chậm. Viết lại để đạt cả giới hạn chu kỳ và giới hạn byte mã.", "start": "; Bài tập 3: ghi 4 phím vào kq theo thứ tự ngược\n; Bản này đúng nhưng chậm: cất từng phím vào ngăn xếp\n; rồi lấy ra ghi kq[0], kq[1]... Hãy viết lại cho đạt\n; giới hạn chu kỳ và byte mã.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkq      DB      4 DUP(?)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     CX, 4\ndoc:\n        MOV     AH, 08H\n        INT     21H\n        PUSH    AX                      ; 11 chu kỳ\n        LOOP    doc\n        MOV     CX, 4\n        MOV     SI, 0\nghi:\n        POP     AX                      ; 8 chu kỳ\n        MOV     kq[SI], AL              ; 9 + 9 = 18 chu kỳ\n        INC     SI\n        LOOP    ghi\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "ABCD", "mem": [{"at": "kq", "bytes": [68, 67, 66, 65]}]}, {"in": "1234", "mem": [{"at": "kq", "bytes": [52, 51, 50, 49]}]}, {"in": "aaaa", "mem": [{"at": "kq", "bytes": [97, 97, 97, 97]}]}, {"in": "z  ~", "mem": [{"at": "kq", "bytes": [126, 32, 32, 122]}]}, {"in": "0909", "mem": [{"at": "kq", "bytes": [57, 48, 57, 48]}]}, {"in": "#$%&", "mem": [{"at": "kq", "bytes": [38, 37, 36, 35]}]}], "perf": {"cycles": 440, "bytes": 30}}]);

makeQuiz("quiz21","score21",[{"q": "SS = 0712h, SP = 0100h. Sau <code>PUSH AX<\/code> với AX = 1234h, SP và hai byte vừa ghi là gì?", "o": ["SP = 0102h; byte 34h ở 07222h, byte 12h ở 07223h", "SP = 00FEh; byte 34h ở 0721Eh, byte 12h ở 0721Fh", "SP = 00FEh; byte 12h ở 0721Eh, byte 34h ở 0721Fh", "SP = 00FFh; chỉ byte 34h được ghi ở 0721Fh"], "a": 1, "e": "PUSH giảm SP 2 trước rồi mới ghi: SP = 00FEh, địa chỉ vật lý 0712h × 16 + 00FEh = 0721Eh. Word ghi byte thấp (34h) ở địa chỉ thấp (Bài 8). Ngăn xếp lớn về phía địa chỉ thấp nên SP không tăng."}, {"q": "Đoạn code sau chạy xong, AX và BX bằng bao nhiêu?<pre class=\"mp-asm\">        MOV     AX, 1\n        MOV     BX, 2\n        PUSH    AX\n        PUSH    BX\n        POP     AX\n        POP     BX<\/pre>", "o": ["AX = 1, BX = 2", "AX = 2, BX = 1", "AX = 2, BX = 2", "AX = 1, BX = 1"], "a": 1, "e": "POP lấy word được PUSH gần nhất: POP AX nhận 2 (giá trị BX đã cất sau), POP BX nhận 1. Đây là cách đổi chỗ qua ngăn xếp (Ví dụ 8); muốn giữ nguyên thì POP BX trước."}, {"q": "Dòng nào báo lỗi khi dịch cho 8086?", "o": ["<code>PUSH DS<\/code>", "<code>PUSH WORD PTR [BX]<\/code>", "<code>PUSH AL<\/code>", "<code>POP ES<\/code>"], "a": 2, "e": "PUSH/POP của 8086 chỉ làm việc với word: thanh ghi 16 bit, thanh ghi đoạn hoặc word bộ nhớ. Muốn cất AL thì PUSH AX. PUSH DS, PUSH WORD PTR [BX], POP ES đều hợp lệ."}, {"q": "Chương trình có <code>.STACK 10h<\/code> và một vòng lặp chạy 9 lần, mỗi lần một <code>PUSH CX<\/code>, không POP. Điều gì xảy ra trên 8086?", "o": ["CPU sinh ngắt tràn ngăn xếp và DOS dừng chương trình kèm thông báo", "Lệnh PUSH thứ 9 bị bỏ qua vì SP đã chạm giới hạn của .STACK", "Word thứ 9 ghi ra ngoài vùng 16 byte, đè lên ô nhớ ngay dưới mà CPU không báo", "Trình dịch báo lỗi vì số lần PUSH vượt kích thước khai báo"], "a": 2, "e": "8086 không có thanh ghi giới hạn ngăn xếp và không kiểm tra; .STACK chỉ là lượng nhớ xin trước. Trình dịch không đếm số lần PUSH lúc chạy. Ví dụ 6 cho thấy biến canh bị đè."}, {"q": "Cần chép thanh ghi đoạn DS sang ES mà <b>không<\/b> được làm hỏng thanh ghi đa dụng nào. Cách nào đúng và ít byte nhất?", "o": ["<code>MOV AX, DS<\/code> / <code>MOV ES, AX<\/code> (4 byte, 4 chu kỳ)", "<code>MOV ES, DS<\/code> (2 byte, 2 chu kỳ)", "<code>XCHG ES, DS<\/code> (2 byte, 4 chu kỳ)", "<code>PUSH DS<\/code> / <code>POP ES<\/code> (2 byte, 18 chu kỳ)"], "a": 3, "e": "8086 không có MOV hay XCHG giữa hai thanh ghi đoạn, nên hai lựa chọn cuối không dịch được. MOV qua AX nhanh hơn nhưng ghi đè AX, trái yêu cầu. PUSH DS / POP ES dùng ngăn xếp làm chỗ trung gian (Ví dụ 3)."}]);

